package com.mhtextractor.config;

import lombok.Data;

/**
 * 主界面 GUI 状态（提取模式、输入/输出目录、完成后打开输出文件夹、界面语言）。
 * 持久化为 logs/gui-state.json，程序启动时恢复；永远只保留一份。
 */
@Data
public class GuiState {

    private boolean imageModeEnabled;
    private String inputFolder;
    private String outputFolder;
    private boolean openFolderAfterComplete;

    /**
     * 功能一：只提取列表中被勾选的项目（默认 false = 提取全部可见项）。
     * 与 openFolderAfterComplete 同构，随 logs/gui-state.json 持久化。
     */
    private boolean extractCheckedOnly;

    /**
     * 界面语言，形如 "zh_CN" / "en_US"；null 或空白 = 跟随系统默认（见 I18n.parseLocale）。
     * 持久化契约与语言无关：该字段只是"选择哪种语言"的偏好值，切换语言不改变 JSON 结构。
     */
    private String locale;
}
package com.mhtextractor.config;

import com.fasterxml.jackson.databind.DeserializationFeature;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.mhtextractor.i18n.I18n;
import lombok.extern.slf4j.Slf4j;

import java.io.File;
import java.io.IOException;

/**
 * 主界面 GUI 状态的单一 JSON 持久化（logs/gui-state.json）。
 * 保存时覆盖写入，始终只有一份文件；加载失败/文件缺失时返回 null，走默认启动逻辑。
 */
@Slf4j
public class GuiStateManager {

    private static final String STATE_DIR = "logs";
    private static final String STATE_FILE = "gui-state.json";

    private static final ObjectMapper objectMapper = new ObjectMapper()
            .configure(DeserializationFeature.FAIL_ON_UNKNOWN_PROPERTIES, false);

    private GuiStateManager() {
    }

    public static GuiState load() {
        return load(new File(STATE_DIR));
    }

    /** 从指定目录加载（单元测试用） */
    static GuiState load(File dir) {
        File file = new File(dir, STATE_FILE);
        if (!file.exists()) {
            return null;
        }
        try {
            return objectMapper.readValue(file, GuiState.class);
        } catch (IOException e) {
            log.warn(I18n.msg("log.guistatemanager.01", e.getMessage()));
            return null;
        }
    }

    public static void save(GuiState state) {
        save(state, new File(STATE_DIR));
    }

    /** 保存到指定目录（单元测试用） */
    static void save(GuiState state, File dir) {
        if (!dir.exists() && !dir.mkdirs()) {
            log.warn(I18n.msg("log.guistatemanager.02", dir.getAbsolutePath()));
            return;
        }
        try {
            objectMapper.writerWithDefaultPrettyPrinter()
                    .writeValue(new File(dir, STATE_FILE), state);
        } catch (IOException e) {
            log.warn(I18n.msg("log.guistatemanager.03", e.getMessage()));
        }
    }
}
package com.mhtextractor.app;

import com.mhtextractor.config.GuiState;
import com.mhtextractor.config.GuiStateManager;

/**
 * GUI 会话状态持久化（logs/gui-state.json）的无头服务（P3-3b-5）：把
 * {@code gui.controller.MainController} 的 {@code restoreGuiState}/{@code saveGuiState}
 * 对 {@link GuiState}/{@link GuiStateManager} 的直接使用原样下沉到 app 层 ——
 * 持久化文件路径/字段名/读写语义/时序一律不变（只搬不改）。
 *
 * <p>locale 拼接规则（{@code language + "_" + country}，country 为空则不加后缀）仍留在 gui 层
 * 由 {@code I18n.currentLocale()} 算好后传入，本类只透传已拼好的字符串。</p>
 *
 * <p>本类<b>零 JavaFX、零 I18n</b>，属 {@code app} 层。</p>
 */
public final class SessionStateService {

    private SessionStateService() {
    }

    /**
     * 会话状态快照：与 {@link GuiState} 字段一一对应
     * （inputFolder / outputFolder / openFolderAfterComplete / extractCheckedOnly /
     * imageModeEnabled / locale）。
     */
    public record Session(
            String inputFolder,
            String outputFolder,
            boolean openFolderAfterComplete,
            boolean extractCheckedOnly,
            boolean imageModeEnabled,
            String locale) {
    }

    /**
     * 加载会话：转调 {@link GuiStateManager#load()}，null 原样返回 null（文件缺失/加载失败
     * 与搬迁前 {@code restoreGuiState} 的短路语义一致），否则逐字段映射。
     */
    public static Session load() {
        GuiState state = GuiStateManager.load();
        if (state == null) {
            return null;
        }
        return new Session(
                state.getInputFolder(),
                state.getOutputFolder(),
                state.isOpenFolderAfterComplete(),
                state.isExtractCheckedOnly(),
                state.isImageModeEnabled(),
                state.getLocale());
    }

    /**
     * 保存会话：内部 {@code new GuiState()}，按搬迁前 {@code MainController.saveGuiState} 的
     * 同序 set（imageModeEnabled → inputFolder → outputFolder → openFolderAfterComplete →
     * extractCheckedOnly → locale），最后 {@link GuiStateManager#save(GuiState)}。
     */
    public static void save(Session session) {
        GuiState state = new GuiState();
        state.setImageModeEnabled(session.imageModeEnabled());
        state.setInputFolder(session.inputFolder());
        state.setOutputFolder(session.outputFolder());
        state.setOpenFolderAfterComplete(session.openFolderAfterComplete());
        state.setExtractCheckedOnly(session.extractCheckedOnly());
        state.setLocale(session.locale());
        GuiStateManager.save(state);
    }
}
package com.mhtextractor.config;

import com.fasterxml.jackson.databind.DeserializationFeature;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.SerializationFeature;
import com.fasterxml.jackson.datatype.jsr310.JavaTimeModule;
import com.mhtextractor.i18n.I18n;
import com.mhtextractor.model.AppConfig;
import lombok.extern.slf4j.Slf4j;

import java.io.File;
import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.List;

/**
 * 配置管理器，负责加载、保存、列出和删除JSON格式的AppConfig
 */
@Slf4j
public class ConfigManager {

    private static final String CONFIG_DIR = "config";
    private static final String CONFIG_EXTENSION = ".json";
    private static final ObjectMapper objectMapper;

    static {
        objectMapper = new ObjectMapper();
        objectMapper.registerModule(new JavaTimeModule());
        objectMapper.configure(SerializationFeature.WRITE_DATES_AS_TIMESTAMPS, false);
        objectMapper.enable(SerializationFeature.INDENT_OUTPUT);
        // 旧版配置含 imageMode/inputFolder/previewBeforeExtract 等已废弃字段，加载时忽略
        objectMapper.configure(DeserializationFeature.FAIL_ON_UNKNOWN_PROPERTIES, false);
    }

    public ConfigManager() {
        try {
            Files.createDirectories(Path.of(CONFIG_DIR));
        } catch (IOException e) {
            log.warn(I18n.msg("log.configmanager.01", CONFIG_DIR, e.getMessage()));
        }
    }

    public void saveConfig(String configName, AppConfig config) throws IOException {
        File configFile = new File(CONFIG_DIR, configName + CONFIG_EXTENSION);
        objectMapper.writeValue(configFile, config);

    }

    public AppConfig loadConfig(String configName) throws IOException {
        File configFile = new File(CONFIG_DIR, configName + CONFIG_EXTENSION);
        if (!configFile.exists()) {
            throw new IOException("Configuration file not found: " + configFile.getAbsolutePath());
        }
        return objectMapper.readValue(configFile, AppConfig.class);
    }

    public List<String> getConfigNames() {
        File configDir = new File(CONFIG_DIR);
        if (!configDir.exists() || !configDir.isDirectory()) {
            return new ArrayList<>();
        }
        List<String> configNames = new ArrayList<>();
        File[] files = configDir.listFiles();
        if (files != null) {
            for (File file : files) {
                if (file.getName().endsWith(CONFIG_EXTENSION)) {
                    configNames.add(file.getName().substring(0, file.getName().length() - CONFIG_EXTENSION.length()));
                }
            }
        }
        return configNames;
    }

    public void deleteConfig(String configName) throws IOException {
        File configFile = new File(CONFIG_DIR, configName + CONFIG_EXTENSION);
        if (!configFile.exists()) {
            throw new IOException("Configuration file not found: " + configFile.getAbsolutePath());
        }
        if (!configFile.delete()) {
            throw new IOException("Failed to delete configuration file: " + configFile.getAbsolutePath());
        }
    }
}
package com.mhtextractor.gui.controller;

import com.mhtextractor.app.NamedConfigService;
import com.mhtextractor.app.Texts;
import com.mhtextractor.model.AppConfig;
import com.mhtextractor.gui.component.NotificationHost;
import javafx.scene.control.TextInputDialog;
import lombok.extern.slf4j.Slf4j;
import org.kordamp.ikonli.fontawesome5.FontAwesomeSolid;

/**
 * 参数面板的「宿主侧动作」：命名配置 CRUD（保存 / 加载 / 删除）与「高速内存模式」确认卡。
 *
 * <p><b>为什么单独一个类</b>：Q6a 起同一个 {@link ParamFormPane} 有两个宿主
 * （模态窗口壳与非模态侧边栏），D 起只剩侧边栏 {@link ParamSidePanel}。
 * 这两段动作里带日志键（{@code log.paramdialogcontroller.01..06}）与提醒卡片文案，
 * <b>属产品行为</b>：复制一份会让日志调用点凭空翻倍（本项目对 {@code log.*} 逐键对账），
 * 所以抽成共用件，两个宿主各自 {@code new ParamPanelActions(pane).install()} 一次即可，
 * 文案 / 图标 / 日志键与拆分前逐字一致。</p>
 *
 * <p>它<b>不持窗口</b>：命名配置名仍走既有的模态 {@link TextInputDialog}（产品语义不变），
 * 提醒卡片的锚点就是面板里的控件（{@code configComboBox} / {@code highSpeedMemoryCheck}），
 * 由 {@code NotificationHost} 落到控件所在窗口的提醒层上 —— 侧边栏场景下自然落在主窗口，
 * 不再另开窗口。</p>
 *
 * <p>包级可见：它是 {@code ParamFormPane} 的宿主侧实现细节，需要访问面板的包级接缝
 * （{@code applyLoadedConfig} / {@code setConfigNames} / {@code highSpeedMemoryCheck}）。</p>
 */
@Slf4j
final class ParamPanelActions {

    private final ParamFormPane pane;
    private final NamedConfigService namedConfigService = new NamedConfigService();

    ParamPanelActions(ParamFormPane pane) {
        this.pane = pane;
    }

    /** 接线：命名配置三动作 + 高速内存模式监听 + 配置列表初值。调用时机与拆分前一致。 */
    void install() {
        pane.setNamedConfigActions(this::saveNamedConfig, this::loadNamedConfig, this::deleteNamedConfig);
        // 高速内存模式警告（ToggleSwitch 不支持 onAction，改用属性监听）
        pane.highSpeedMemoryCheck.selectedProperty().addListener((obs, old, newVal) -> {
            if (newVal) {
                onHighSpeedMemoryChanged();
            }
        });
        refreshConfigList();
    }

    // ==================== 配置管理（加载只填充当前模式参数组） ====================

    private void saveNamedConfig() {
        TextInputDialog dialog = new TextInputDialog("my_config");
        dialog.setTitle(Texts.get("dialog.saveConfig"));
        dialog.setHeaderText(Texts.get("dialog.inputConfigName"));
        dialog.setContentText(Texts.get("dialog.saveConfigNote"));
        dialog.showAndWait().ifPresent(name -> {
            try {
                namedConfigService.save(name, pane.collect());
                refreshConfigList();
                pane.configComboBox.getSelectionModel().select(name);
                log.info(Texts.msg("log.paramdialogcontroller.01", name));
            } catch (Exception e) {
                log.error(Texts.msg("log.paramdialogcontroller.02"), e);
                NotificationHost.error(pane.configComboBox, Texts.get("error.CONFIG_SAVE_FAILED"), FontAwesomeSolid.SAVE);
            }
        });
    }

    private void loadNamedConfig() {
        String selected = pane.configComboBox.getSelectionModel().getSelectedItem();
        if (selected == null) {
            NotificationHost.toastWarning(pane.configComboBox, Texts.get("error.CONFIG_SELECT_TO_LOAD"), FontAwesomeSolid.HAND_POINTER);
            return;
        }
        try {
            AppConfig config = namedConfigService.load(selected);
            // 只填充当前模式参数组，另一组保持隔离（确定后才生效）
            pane.applyLoadedConfig(config);
            log.info(Texts.msg("log.paramdialogcontroller.03", selected));
        } catch (Exception e) {
            log.error(Texts.msg("log.paramdialogcontroller.04"), e);
            NotificationHost.error(pane.configComboBox, Texts.get("error.CONFIG_LOAD_FAILED"), FontAwesomeSolid.FILE_DOWNLOAD);
        }
    }

    private void deleteNamedConfig() {
        String selected = pane.configComboBox.getSelectionModel().getSelectedItem();
        if (selected == null) {
            NotificationHost.toastWarning(pane.configComboBox, Texts.get("error.CONFIG_SELECT_TO_DELETE"), FontAwesomeSolid.HAND_POINTER);
            return;
        }
        NotificationHost.confirm(pane.configComboBox,
                Texts.get("error.CONFIG_DELETE_CONFIRM", "name", selected), FontAwesomeSolid.TRASH_ALT, ok -> {
                    if (!ok) {
                        return;
                    }
                    try {
                        namedConfigService.delete(selected);
                        refreshConfigList();
                        log.info(Texts.msg("log.paramdialogcontroller.05", selected));
                    } catch (Exception e) {
                        log.error(Texts.msg("log.paramdialogcontroller.06"), e);
                        NotificationHost.error(pane.configComboBox, Texts.get("error.CONFIG_DELETE_FAILED"), FontAwesomeSolid.TRASH_ALT);
                    }
                });
    }

    private void refreshConfigList() {
        pane.setConfigNames(namedConfigService.names());
    }

    /** 高速内存模式确认（会话 19：窗口内居中确认卡片，取代嵌套模态 Alert） */
    private void onHighSpeedMemoryChanged() {
        if (pane.highSpeedMemoryCheck.isSelected()) {
            String msg = Texts.get("dialog.highSpeedConfirmTitle") + "\n"
                    + Texts.get("dialog.highSpeedConfirmMsg");
            NotificationHost.confirm(pane.highSpeedMemoryCheck, msg, FontAwesomeSolid.MEMORY, ok -> {
                if (!ok) {
                    pane.highSpeedMemoryCheck.setSelected(false);
                }
            });
        }
    }
}

