    void setGlobalParams(boolean imageMode, com.mhtextractor.model.AppConfig params);

    /**
     * 组参数写入（{@code applyGroupParams} 语义）：写入该组当前模式参数缓存，压 PARAM_SET
     * 撤销记录，失效该组未移除成员的磁盘缓存，并发布 {@code ParamStateChanged(SET_GROUP, 成员路径)}。
