    void events(Consumer<ObjectNode> sink) { events = sink; }

    IpcFiles files() { return files; }

    void silentChanges(Runnable changed) { silentChange = changed; }

    void drainCallbacks() {
        for (int i = 0; i < 256; i++) {
            var callback = callbacks.poll();
            if (callback == null) return;
            callback.run();
        }
    }

    void inputPump(Runnable pump) { inputPump = pump; }

    void disconnect() {
        if (disconnecting) return;
        disconnecting = true;
        try {
            // Mark the run cancelled before waking its confirmation waiter; otherwise it may win a natural-completion race.
            port.commands().cancelExtraction();
        } finally {
            confirmations.disconnect(); // Also release import confirmations, even if terminal delivery broke stdout.
            if (port.queries().previewLoadingPath() != null
                    || workers.stream().anyMatch(t -> t.isAlive() && t.getName().equals("preview-preparse")))
                port.commands().cancelWorkspaceActivity();
        }
    }

    private AppConfig params(PreviewItem item, boolean mode) {
        AppConfig config = ParamScope.effectiveParams(item.parentGroup, item.textItemParams,
                item.imageItemParams, mode, global.text(), global.image());
        return config == null ? new AppConfig() : config;
    }

    private void dispatch(Runnable callback) {
        if (closing) return;
        if (Thread.currentThread() == host) { callback.run(); return; }
        String workerName = Thread.currentThread().getName();
        if (workerName.startsWith("preview-") || workerName.startsWith("mht-import-") || workerName.startsWith("extraction-"))
            workers.add(Thread.currentThread());
        boolean interrupted = false;
        try {
            while (!closing) {
                try {
                    if (callbacks.offer(callback, 25, TimeUnit.MILLISECONDS)) break;
                } catch (InterruptedException e) { interrupted = true; }
            }
            queuePeak = Math.max(queuePeak, callbacks.size());
        } finally {
            if (interrupted) Thread.currentThread().interrupt();
        }
    }

    private void start(Runnable command) {
        var before = Thread.getAllStackTraces().keySet();
        command.run();
        // Existing app coordinators create these workers synchronously before returning.
        // Keep their handles so shutdown also joins a parser that has not delivered a callback yet.
        Thread.getAllStackTraces().keySet().stream().filter(t -> !before.contains(t))
                .filter(t -> t.getName().equals("preview-preparse") || t.getName().equals("preview-image-load")
                        || t.getName().equals("mht-import-scan")).forEach(workers::add);
    }

    boolean busy() { return extractions.running.get() || importing || !pendingNotices.isEmpty() || port.queries().previewLoadingPath() != null
            || workers.stream().anyMatch(t -> t.isAlive() && t.getName().equals("preview-preparse")); }

    private void await(java.util.function.BooleanSupplier done) throws InterruptedException {
        // Synchronous methods finish their activity before responding; no worker touches the model afterward.
        while (!done.getAsBoolean()) {
            inputPump.run();
            Runnable callback = callbacks.poll(25, TimeUnit.MILLISECONDS);
            if (callback != null) callback.run();
        }
    }

    private void emit(String name, ObjectNode data) {
        ObjectNode frame = json.createObjectNode().put("v", 1).put("type", "event").put("event", name);
        IpcFailure problem = classify(error);
        if (failure.complete(problem)) {
            status = new BackendSession.Status(problem.kind() == IpcFailure.Kind.UNAVAILABLE
                    ? BackendSession.State.UNAVAILABLE : BackendSession.State.DISCONNECTED,problem.getMessage());
            files.invalidate(); confirmer.close(); session.close();
        }
    }
    private IpcFailure classify(Throwable e) {
        while ((e instanceof ExecutionException || e instanceof CompletionException) && e.getCause() != null) e = e.getCause();
        if (e instanceof IpcFailure f) return f;
        if (e instanceof BackendSession.RemoteError r) return new IpcFailure(IpcFailure.Kind.REMOTE,r.code(),r.getMessage(),r);
        return new IpcFailure(e instanceof TimeoutException ? IpcFailure.Kind.TIMEOUT : IpcFailure.Kind.PROTOCOL,null,e.getMessage(),e);
    }
    private IpcFailure startupFailure(String detail, Throwable cause) {
        boolean mismatch = detail != null && (detail.contains("mismatch") || detail.contains("required capabilities")
                || detail.contains("Malformed") || detail.contains("Expected backend") || detail.contains("handshake rejected"));
        return new IpcFailure(mismatch ? IpcFailure.Kind.PROTOCOL : IpcFailure.Kind.UNAVAILABLE,null,detail,cause);
    }
    private <T> T await(CompletableFuture<T> future) {
        return await(future,requestTimeout);
    }
    private <T> T await(CompletableFuture<T> future,Duration timeout) {
        try { return future.get(timeout.toMillis(),TimeUnit.MILLISECONDS); }
        catch (InterruptedException e) { Thread.currentThread().interrupt(); throw classify(e); }
        catch (ExecutionException | TimeoutException e) { throw classify(e); }
    }
    private void check() {
        if (closed) throw new IpcFailure(IpcFailure.Kind.CLOSED,null,"IPC port closed",null);
        if (failure.isDone()) throw failure.join();
    }
    private JsonNode raw(String method, JsonNode params) {
        check();
        try { return await(session.request(method,params)); }
        catch (IpcFailure e) {
            if (e.kind() != IpcFailure.Kind.REMOTE) fail(e);
            throw e;
        }
    }
    private JsonNode call(String method, JsonNode params) {
        check();
        if (!List.of("cancelWorkspaceActivity","cancelPreviewLoad","resolvePreviewRegion",
                "activityGeneration","previewGeneration","previewLoadingPath","startPreparse","startPreparseFor",
                "refreshPreparseProgress","loadPreview","awaitPreviewInFlight","startExtraction","cancelExtraction").contains(method)) {
            // Never ask for a cached snapshot until earlier FileRefs have been revoked on the server.
            await(releases());
        }
        JsonNode result = raw(method,params); barrier(); check(); return result;
    }
